#ifndef _QUAKE_LIR_SNAPSHOT_H_
#define _QUAKE_LIR_SNAPSHOT_H_
#include "base.h"
#include "deopt.h"
#include "ir/checkpoint.h"

namespace quake {

namespace ir {
class Type;
class SSAVar;
class Checkpoint;
}  // namespace ir

namespace lir {
class HOperand;

// Snapshot is a materialized checkpoint, used by Deopt to materialize itself's
// inner gut. Notes, snapshot is mostly a transient data structure generated
// after the RA and will be used to populate deopt entry

class Snapshot {
 public:
  // This mapping is generated by RA to indicate the SSAVar to its *CURRENT*
  // HOperand value.
  using SSAVarMappings = std::map<ir::SSAVar*, lir::HOperand*>;

 public:
  Snapshot() = default;

  // Called by RA to initialize/construct the Snapshot object and use it to
  // feed the Deopt object
  void Construct(const SSAVarMappings&, const ir::Checkpoint&);

  bool happen_before() const { return happen_before_; }

 private:
  static Deopt::ValueOrigin MapOrigin(ir::Checkpoint::Type);
  static int MapJValType(const ir::Type&);
  static Deopt::MachineRef MapMachineRef(ir::SSAVar*, const SSAVarMappings&);

 private:
  std::vector<Deopt::Frame> frame_;

  bool happen_before_;

  // frame_ will be stolen by the Deopt object to store into the global Quake
  // object for later rematerialization usage
  friend class quake::Deopt;
};

}  // namespace lir
}  // namespace quake

#endif  // _QUAKE_LIR_SNAPSHOT_H_
